interface.definition:
a!localVariables(
  /* Guard: only query when orgid is present */
  local!orgRecords: if(
    a!isNotNullOrEmpty(ri!orgid),
    #"_a-0000eef8-4604-8000-9e54-011c48011c48_1123673"(
      orgid: ri!orgid,
      isActive: true()
    ),
    {}
  ),
  /* Unwrap to single record */
  local!org: if(
    a!isNotNullOrEmpty(local!orgRecords),
    index(local!orgRecords, 1, {}),
    {}
  ),
  local!hasOrg: a!isNotNullOrEmpty(local!org),

  /*----- Organization Details -----*/
  #"SYSTEM_SYSRULES_sectionLayout_v1"(
    label: "",
    labelSize: "MEDIUM",
    contents: {
      #"SYSTEM_SYSRULES_richTextDisplayField"(
        labelPosition: "COLLAPSED",
        value: {
          #"SYSTEM_SYSRULES_richTextIcon"(icon: "info-circle", color: "ACCENT"),
          #"SYSTEM_SYSRULES_richTextItem_v1"(
            text: " Basic Details",
            size: "MEDIUM",
            style: "STRONG"
          )
        },
        marginBelow: "STANDARD"
      ),
      #"SYSTEM_SYSRULES_cardLayout"(
        contents: {
          if(
            not(local!hasOrg),
            /* Empty state */
            #"SYSTEM_SYSRULES_richTextDisplayField"(
              labelPosition: "COLLAPSED",
              value: {
                #"SYSTEM_SYSRULES_richTextIcon"(icon: "info-circle", color: "SECONDARY", size: "LARGE"),
                char(10), char(10),
                #"SYSTEM_SYSRULES_richTextItem_v1"(
                  text: "No organization details available.",
                  color: "SECONDARY"
                )
              },
              align: "CENTER"
            ),
            /* Populated state */
            #"SYSTEM_SYSRULES_columnsLayout"(
              columns: {
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: {
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Organization Name",
                      labelPosition: "JUSTIFIED",
                      value: a!defaultValue(
                        local!org[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/0f073a93-5255-4fd3-bdba-87d2febf50e9"],
                        "–"
                      ),
                      marginBelow: "MORE"
                    ),
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Organization ID",
                      labelPosition: "JUSTIFIED",
                      value: if(
                        a!isNullOrEmpty(
                          local!org[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/5793af42-009b-4cef-b5b5-7c4a81f902ec"]
                        ),
                        "–",
                        text(
                          local!org[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/5793af42-009b-4cef-b5b5-7c4a81f902ec"],
                          "00000"
                        )
                      ),
                      marginBelow: "MORE"
                    ),
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Organization Type",
                      labelPosition: "JUSTIFIED",
                      value: if(
                        a!defaultValue(
                          local!org[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/56279cd7-e7c5-4577-9c40-eae4b315ac12"],
                          false
                        ) = true,
                        {
                          #"SYSTEM_SYSRULES_richTextIcon"(icon: "building", color: "ACCENT"),
                          #"SYSTEM_SYSRULES_richTextItem_v1"(text: " Parent", style: "STRONG")
                        },
                        {
                          #"SYSTEM_SYSRULES_richTextIcon"(icon: "share-alt", color: "SECONDARY"),
                          #"SYSTEM_SYSRULES_richTextItem_v1"(text: " Child", color: "SECONDARY")
                        }
                      )
                    )
                  }
                ),
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: {
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Manager",
                      labelPosition: "JUSTIFIED",
                      value: a!defaultValue(
                        #"_a-0000eef8-4604-8000-9e54-011c48011c48_1121809"(
                          local!org[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/4b67e544-964e-485d-90df-3947cc4b80b2"]
                        ),
                        "–"
                      ),
                      marginBelow: "MORE"
                    ),
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Email",
                      labelPosition: "JUSTIFIED",
                      value: a!defaultValue(
                        local!org[#"urn:appian:record-relationship:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/60f9ea53-2ab2-479b-a990-a1eac9caaa33".],
                        "–"
                      ),
                      marginBelow: "MORE"
                    ),
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Phone Number",
                      labelPosition: "JUSTIFIED",
                      value: a!defaultValue(
                        local!org[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/a33eb1be-a4a5-47f5-83dc-a9c46ab51447/0da43122-5b32-4aea-89b6-d626dc2f2d61"],
                        "–"
                      ),
                      marginBelow: "MORE"
                    )
                  }
                ),
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: {
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Address Line 1",
                      labelPosition: "JUSTIFIED",
                      value: a!defaultValue(
                        local!org[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/60f9ea53-2ab2-479b-a990-a1eac9caaa33/f19ea19e-f942-445d-a2b3-1e55c08cf38b"],
                        "–"
                      ),
                      marginBelow: "MORE"
                    ),
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "City, State",
                      labelPosition: "JUSTIFIED",
                      value: {
                        a!defaultValue(
                          local!org[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/60f9ea53-2ab2-479b-a990-a1eac9caaa33/e08539a9-3fd9-44a3-af1f-9a76bece830a/2ce57781-e8d2-4da6-b4df-f1770d496384"],
                          "–"
                        ),
                        ", ",
                        a!defaultValue(
                          local!org[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/60f9ea53-2ab2-479b-a990-a1eac9caaa33/0f2c239a-8630-4c1b-a4b0-33832e28893e/6e63fcd6-66c8-4856-9b35-cd8fc9593e26"],
                          "–"
                        )
                      },
                      marginBelow: "MORE"
                    ),
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Country, Postal Code",
                      labelPosition: "JUSTIFIED",
                      value: {
                        a!defaultValue(
                          local!org[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/60f9ea53-2ab2-479b-a990-a1eac9caaa33/63dfdf89-f8b0-4b96-a5dd-2d7627419cf1/1f76749a-fbe8-4ba5-b8f2-097dcecb789d"],
                          "–"
                        ),
                        ", ",
                        a!defaultValue(
                          local!org[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/60f9ea53-2ab2-479b-a990-a1eac9caaa33/1edbf58a-d2c0-49a8-942c-8dcc8e7d91bc"],
                          "-"
                        )
                      }
                    )
                  }
                ),
                #"SYSTEM_SYSRULES_columnLayout"(
                  contents: {
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Created By",
                      labelPosition: "JUSTIFIED",
                      value: a!defaultValue(
                        #"_a-0000eef8-4604-8000-9e54-011c48011c48_1121809"(
                          local!org[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/ede85cff-8806-4601-8174-efd046a5e27d"]
                        ),
                        "–"
                      ),
                      marginBelow: "MORE"
                    ),
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Created On",
                      labelPosition: "JUSTIFIED",
                      value: a!defaultValue(
                        #"_a-0000eef8-4604-8000-9e54-011c48011c48_1122127"(
                          local!org[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/4612a8c0-d789-4a20-b285-23be421cb15a"]
                        ),
                        "–"
                      ),
                      marginBelow: "MORE"
                    ),
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      label: "Modified By / Modified On",
                      labelPosition: "JUSTIFIED",
                      value: {
                        a!defaultValue(
                          #"_a-0000eef8-4604-8000-9e54-011c48011c48_1121809"(
                            local!org[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/fd8f4b42-8bca-4747-94ca-c46cc6c74ba4"]
                          ),
                          "–"
                        ),
                        ", ",
                        a!defaultValue(
                          #"_a-0000eef8-4604-8000-9e54-011c48011c48_1122127"(
                            local!org[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/8daaa099-d49f-4293-851a-50716290b0af"]
                          ),
                          "–"
                        )
                      }
                    )
                  }
                )
              }
            )
          )
        },
        style: "NONE",
        padding: "STANDARD",
        marginBelow: "STANDARD",
        showBorder: false,
        showShadow: true
      )
    }
  )
)
